from lib import *
r=[]
r.append(R(3919,"कम फॉस्फोरस वाली आटे की टॉर्टिला","किडनी रोग वाले और डायलिसिस पर रहने वाले लोगों के लिए कई खाद्य पदार्थ सीमित होते हैं, लेकिन कैनसस की DaVita रीनल आहार विशेषज्ञ मैरी की घर पर बनी फॉस्फोरस-रहित बेकिंग पाउडर की रेसिपी की बदौलत उनकी आसान कम फॉस्फोरस वाली टॉर्टिला जैसे खाद्य पदार्थ फिर से आपके मेन्यू में शामिल हो गए हैं।","12 टॉर्टिला","1 टॉर्टिला",
["3 कप मैदा (ऑल-पर्पज़ व्हाइट फ़्लोर)","2 छोटे चम्मच घर पर बना फॉस्फोरस-रहित बेकिंग पाउडर","1/4 छोटा चम्मच नमक","3/4 कप शॉर्टनिंग","3/4 कप गरम पानी"],
["मैदा, फॉस्फोरस-रहित बेकिंग पाउडर और नमक मिलाएँ।","शॉर्टनिंग को तब तक काटकर मिलाएँ जब तक मिश्रण भुरभुरा न हो जाए।","3/4 कप गरम पानी डालें और सामग्री के नम दिखने तक चलाएँ।","मिलाएँ और गूँधकर नरम आटा बनाएँ। (आपको 1 से 2 बड़े चम्मच मैदा और छिड़कना पड़ सकता है।)","आटे को तौलिये से ढककर 1 घंटे के लिए रख दें।","12 टुकड़ों में काटें।","हल्के हाथ से 6” से 7” की टॉर्टिला बेलें, या टॉर्टिला प्रेस में डालकर 1/8” मोटाई तक बनाएँ।","गरम लोहे की कड़ाही (तवे) पर हर तरफ़ 30 से 60 सेकंड तक पकाएँ, जब तक आटा कच्चा न रहे और भूरे धब्बे आने लगें।"],
["क्रीम ऑफ़ टार्टर टार्टरिक एसिड का पोटैशियम एसिड नमक है, जो शराब बनाने का उप-उत्पाद है। एक छोटे चम्मच में 495 मिग्रा पोटैशियम होता है। फॉस्फोरस वाले बेकिंग पाउडर की जगह बेकिंग सोडा के साथ क्रीम ऑफ़ टार्टर का उपयोग करते समय ध्यान रखें कि भोजन में पोटैशियम की मात्रा अधिक होगी लेकिन फॉस्फोरस बहुत कम होगा।","चूँकि कम फॉस्फोरस वाले बेकिंग पाउडर से बनी टॉर्टिला में पोटैशियम सामान्य टॉर्टिला से अधिक होता है, इसलिए अगर आप कम पोटैशियम वाला आहार ले रहे हैं तो मात्रा और पोटैशियम के अन्य स्रोतों को सीमित रखना सुनिश्चित करें।"],
["1-1/2 स्टार्च","2 वसा"]))
r.append(R(3920,"स्वीट एंड सावर एशियन श्रिंप","स्वीट एंड सावर ओरिएंटल श्रिंप को सफ़ेद चावल और सब्जियों के साथ परोसें, यह किडनी-अनुकूल भोजन सबको स्वादिष्ट लगेगा।","4","1/2 कप चावल पर 1-1/4 कप",
["2 बड़े चम्मच सेलेरी","2 बड़े चम्मच प्याज़","1/2 कप हरी शिमला मिर्च","1/2 कप डिब्बाबंद, कटे सिंघाड़े (वॉटर चेस्टनट)","1/2 कप गाजर","16 औंस बड़े, छिलके वाले कच्चे झींगे","1 बड़ा चम्मच कैनोला तेल","1/4 छोटा चम्मच तीखा मिर्च का तेल","2 कप गरम पका हुआ सफ़ेद चावल","2 बड़े चम्मच नींबू का रस","1/3 कप पानी","1 बड़ा चम्मच दबाकर भरी हुई ब्राउन शुगर","1-1/2 छोटे चम्मच कम सोडियम वाला सोया सॉस","1 छोटा चम्मच अदरक","1 छोटा चम्मच कॉर्नस्टार्च"],
["सेलेरी और प्याज़ को छोटे टुकड़ों में काटें। शिमला मिर्च और गाजर के स्लाइस काटें। झींगों को छीलें और उनकी नस निकाल दें।","गाजर को माइक्रोवेव-सुरक्षित डिश में रखें। 2 बड़े चम्मच पानी डालें, ढककर 3 मिनट पकाएँ। पानी निथार दें।","एक बड़ी नॉनस्टिक फ्राइंग पैन या कड़ाही में दोनों तेल गरम करें। सेलेरी, प्याज़, हरी शिमला मिर्च और निथारे हुए सिंघाड़े डालें। 3 मिनट तक तेज़ आँच पर चलाते हुए भूनें। पकी हुई गाजर डालकर गरम करें। झींगे डालें और झींगों के बस गुलाबी होने तक, लगभग 2 मिनट, चलाते और धीमी आँच पर पकाते रहें। फ्राइंग पैन को आँच से उतार लें।","एक छोटे कटोरे में नींबू का रस, पानी, ब्राउन शुगर, सोया सॉस, कद्दूकस किया अदरक और कॉर्नस्टार्च मिलाएँ।","मिश्रण को चलाएँ और सब्जियों तथा झींगों में डालें। उबाल आने दें, फिर आँच मध्यम कर दें। सॉस के गाढ़ा होने तक पकाएँ।","4 हिस्सों में बाँटें और हर हिस्से को 1/2 कप गरम चावल पर परोसें।"],
["जल्दी में हों तो ताज़ी सब्जियों और जमे हुए झींगों की जगह मिलती-जुलती सामग्री वाला जमा हुआ ओरिएंटल सब्जी मिश्रण इस्तेमाल करें।"],
["2 मांस","1-1/2 स्टार्च","1 सब्जी, कम पोटैशियम"]))
r.append(R(3922,"सदर्न-स्टाइल कॉर्नब्रेड-कम फॉस्फोरस","कॉर्नब्रेड अमेरिका के सबसे अच्छे आरामदायक भोजनों में से एक है। और किडनी रोग वाले या डायलिसिस पर रहने वाले लोग भी इसका किडनी-अनुकूल संस्करण, सदर्न-स्टाइल कॉर्नब्रेड-कम फॉस्फोरस, खा सकते हैं।","18","2\" का चौकोर टुकड़ा या रेसिपी का 1/18 हिस्सा",
["1 बड़ा चम्मच वनस्पति तेल","1-3/4 कप ऑल-पर्पज़ सफ़ेद मक्के का आटा (कॉर्न मील)","3 कप मैदा (ऑल-पर्पज़ व्हाइट फ़्लोर)","1/4 कप चीनी या Splenda® चीनी का विकल्प","1 पैकेट Fleishmann’s® Rapid Rise यीस्ट","1 छोटा चम्मच नमक","4 बड़े चम्मच बिना नमक का मक्खन, पिघला हुआ","1/2 कप नॉन-डेयरी क्रीमर","1 कप पानी","2 बड़े अंडे"],
["12″ की कड़ाही (स्किलेट) में तेल लगाएँ और उसे गरम चूल्हे पर रखें।","एक बड़े कटोरे में कॉर्न मील, 1 कप मैदा, चीनी, यीस्ट और नमक मिलाएँ।","मक्खन को माइक्रोवेव में 10-15 सेकंड गरम करके पिघलाएँ। एक अलग बर्तन में नॉन-डेयरी क्रीमर और पानी को 120°-130° F तक गरम करें। पिघला हुआ मक्खन मिलाएँ।","तरल मिश्रण को सूखे मिश्रण में मिलाएँ और इलेक्ट्रिक मिक्सर से तेज़ गति पर 2 मिनट फेंटें। अंडे डालें और तेज़ गति पर 1-2 मिनट और फेंटें।","धीरे-धीरे बचा हुआ मैदा डालें और चलाते रहें ताकि गाढ़ा घोल बन जाए।","घोल को चिकनाई लगी कड़ाही में डालें और उसके आकार में फैलाएँ। ऊपर तेल लगाकर थपथपाएँ, तौलिये से ढकें और किसी गरम जगह पर 45 मिनट फूलने दें।","375° F पर 30 मिनट या ऊपर की परत के सुनहरे भूरे होने तक बेक करें।"],
["यीस्ट वाली ब्रेड बनाना कभी बहुत समय लेने वाला काम हुआ करता था। Fleishmann’s® Rapid Rise यीस्ट तैयारी के चरणों और फूलने के समय को कम कर देता है। इस रेसिपी का घोल 15 से 20 मिनट में तैयार हो सकता है। शुरू से मेज़ तक कुल समय केवल 1-1/2 घंटे है!","यीस्ट वाली ब्रेड बनाने में तापमान बहुत महत्वपूर्ण है। तरल का तापमान 120°-130° F जाँचने के लिए फ़ूड थर्मामीटर का उपयोग करें। फूलने के दौरान आटे को ढककर किसी गरम, हवा रहित जगह पर रखें।","यीस्ट वाला कॉर्नब्रेड क्यों बनाएँ? सभी ब्रेड को ठीक से फूलने के लिए एक खमीरीकरण कारक (लीवनिंग एजेंट) की ज़रूरत होती है। बेकिंग सोडा में सोडियम अधिक होता है, बेकिंग पाउडर में सोडियम और फॉस्फोरस अधिक होते हैं, और क्रीम ऑफ़ टार्टर में पोटैशियम अधिक होता है। इसकी तुलना में यीस्ट में ये सभी तत्व बहुत कम होते हैं। नीचे दी गई तालिका में तुलना करें:"],
["2 स्टार्च","1 वसा"]))
r.append(R(3923,"चेडर मीटलोफ़","फ़्लोरिडा की DaVita रीनल आहार विशेषज्ञ जेनिस के पास एक मीटलोफ़ रेसिपी है जो बहुत स्वादिष्ट है और किडनी आहार में फ़िट बैठती है। इसका स्वाद इसे आपका पसंदीदा मीटलोफ़ बना सकता है।","6","लोफ़ के 1/6 स्लाइस, लगभग 3 औंस",
["1 पाउंड बीफ़ कीमा","1 बड़ा अंडा","1/2 कप बिना मसाले वाले ब्रेड क्रम्ब्स","1/2 कप ब्राउन शुगर","8 औंस कम सोडियम वाला टमाटर सॉस","1 बड़ा चम्मच लहसुन पाउडर","1 बड़ा चम्मच प्याज़ पाउडर","1 औंस कद्दूकस किया हुआ प्राकृतिक चेडर चीज़"],
["ओवन को 350°F पर पहले से गरम करें।","एक कटोरे में बीफ़ कीमा, अंडा, 1/4 कप ब्रेड क्रम्ब्स, ब्राउन शुगर, 3 औंस टमाटर सॉस, लहसुन पाउडर और प्याज़ पाउडर मिलाएँ।","हाथ से अच्छी तरह मिलाएँ। दो बराबर हिस्सों में बाँटें।","एक हिस्से को नॉन-स्टिक स्प्रे लगे कैसरोल डिश में चिकना करके बिछाएँ।","मांस के ऊपर चीज़ बुरकें।","बीफ़ के बाकी मिश्रण को चीज़ के ऊपर चिकना करके बिछाएँ।","बचा हुआ टमाटर सॉस मीटलोफ़ के ऊपर डालें।","बचे हुए ब्रेड क्रम्ब्स मीटलोफ़ के ऊपर बुरकें।","ढककर ओवन में एक घंटे पकाएँ, या बिना ढके माइक्रोवेव ओवन में 70% पावर पर 35 मिनट पकाएँ।"],
["चाहें तो बीफ़ की जगह टर्की कीमा इस्तेमाल करें।","इस मीटलोफ़ में लहसुन बहुत है। अपने स्वाद के अनुसार लहसुन पाउडर और प्याज़ पाउडर की मात्रा समायोजित करें।","1/2 कप ब्राउन शुगर की जगह 1/4 कप Splenda® ब्राउन शुगर ब्लेंड इस्तेमाल करके कार्बोहाइड्रेट को 17 ग्राम तक घटाएँ।","बचे हुए मीटलोफ़ को अलग-अलग सर्विंग में बाँटें, लपेटें और बाद में जल्दी मीटलोफ़ सैंडविच या भोजन के लिए फ्रीज़ कर लें।"],
["2 मांस","1/2 स्टार्च","1 सब्जी, मध्यम पोटैशियम","1/2 उच्च कैलोरी"]))
r.append(R(3924,"व्हाइट क्रिसमस सलाद","व्हाइट क्रिसमस सलाद की यह रेसिपी साल के किसी भी समय स्वादिष्ट लगती है और बचे हुए चिकन या टर्की का उपयोग करने का बढ़िया तरीका है। स्वादिष्ट अंगूर, थोड़े से अखरोट और आपकी पसंद का मुर्गी का मांस मेयोनेज़ और खट्टी क्रीम के साथ मिलाकर बिब लेट्यूस की परत पर रखा जाता है। मैरीलैंड की DaVita रीनल आहार विशेषज्ञ लिन द्वारा भेजा गया यह किडनी-अनुकूल सलाद दोपहर के भोजन के लिए बहुत अच्छा है।","6","1 कप",
["1/4 कप खट्टी क्रीम (सावर क्रीम)","1/4 कप मेयोनेज़","2 कप पकी हुई टर्की","25 लाल बीज रहित अंगूर","25 हरे बीज रहित अंगूर","1/2 कप अखरोट","सजावट के लिए बिब लेट्यूस"],
["एक छोटे कटोरे में खट्टी क्रीम और मेयोनेज़ मिलाएँ।","अंगूरों को आधा काटें; अखरोट को मोटा-मोटा काटें और चिकन को छोटे टुकड़ों में काटें।","एक बड़े कटोरे में टर्की, अंगूर और अखरोट मिलाएँ।","खट्टी क्रीम और मेयोनेज़ को बड़े कटोरे की सामग्री में धीरे से मिलाएँ।","कम से कम एक घंटा ठंडा करें।","कम सोडियम वाले क्रैकर या कुरकुरी ब्रेडस्टिक के साथ लेट्यूस के पत्ते पर ठंडा परोसें।"],
["त्योहार के भोजन से बची टर्की या चिकन का उपयोग करें।","चिकन या टर्की की जगह कटा हुआ एकदम सख़्त टोफू और मोटे कटे मशरूम, या कटे उबले अंडे का सफ़ेद भाग और मोटे कटे मशरूम डालकर बिना मांस वाला सलाद बनाएँ।","अंडे के सफ़ेद भाग वाले विकल्प में, उबले अंडों का सफ़ेद भाग या पके हुए पाश्चुरीकृत तरल अंडे का सफ़ेद भाग इस्तेमाल करें।","मेवों में फॉस्फोरस और पोटैशियम अधिक होता है। मात्रा को 1/2 कप तक सीमित रखने पर अखरोट प्रति सर्विंग 32 मिग्रा फॉस्फोरस और 50 मिग्रा पोटैशियम जोड़ते हैं। चाहें तो न डालें।","वसा के ग्राम आधे करने के लिए कम वसा वाली खट्टी क्रीम और मेयोनेज़ इस्तेमाल करें।"],
["2 मांस","1/2 फल, कम पोटैशियम","2 वसा"]))
r.append(R(3926,"लेमन कुकीज़","मिसौरी की DaVita रीनल आहार विशेषज्ञ फ़े अपने डायलिसिस मरीज़ों को स्वस्थ जीवनशैली और आहार बनाए रखने में मदद के लिए नई और रोमांचक रेसिपी सिखाने की चुनौती स्वीकार करती हैं। फ़े अपनी मुँह में पानी लाने वाली, आसानी से बनने वाली लेमन कुकीज़ साझा करती हैं जो आपके परिवार और दोस्तों को बहुत पसंद आएँगी।","32","2 छोटी कुकीज़ या 1 बड़ी कुकी",
["1 डिब्बा लेमन केक मिक्स","2 कप Truwhip® या Cool Whip® जमा हुआ डेज़र्ट टॉपिंग","1 बड़ा अंडा","1 छोटा चम्मच वनीला एक्सट्रैक्ट","1/2 कप पाउडर चीनी"],
["ओवन को 350° F पर पहले से गरम करें। जमे हुए डेज़र्ट टॉपिंग को पिघलने दें।","कुकी शीट्स पर चिकनाई लगाएँ।","एक बड़े कटोरे में केक मिक्स, डेज़र्ट टॉपिंग, अंडा और वनीला मिलाएँ।","आटे का एक भरा हुआ छोटा चम्मच पाउडर चीनी के कटोरे में डालें और लपेटें। (आटे के गोले बनाना ज़रूरी नहीं है।) बड़ी कुकीज़ के लिए छोटे चम्मच की जगह बड़े चम्मच से आटा डालें।","पाउडर चीनी में लिपटे आटे को चिकनाई लगी कुकी शीट पर रखें।","10 मिनट बेक करें।","कुकीज़ को बेकिंग शीट से हटाने से पहले 2 मिनट ठंडा होने दें।"],
["10 मिनट बाद कुकीज़ पूरी तरह पकी हुई नहीं दिख सकतीं, लेकिन वे ओवन से निकालने के लिए तैयार हैं।","इससे 64 छोटी कुकीज़ (छोटा चम्मच) या 32 बड़ी कुकीज़ (बड़ा चम्मच) बनती हैं।","Truwhip® एक जमा हुआ डेज़र्ट टॉपिंग है जिसमें फॉस्फेट योजक (एडिटिव) नहीं होते।"],
["1 स्टार्च"]))
r.append(R(3927,"स्ट्रॉबेरी एंजेल फ़ूड केक","केंटकी की DaVita आहार विशेषज्ञ लॉरेन के स्ट्रॉबेरी एंजेल फ़ूड केक के एक स्लाइस से अपनी मिठाई की चाहत पूरी करें। यह एक ताज़गी भरी मिठाई है और बिना डायलिसिस वाले CKD, डायलिसिस और मधुमेह-डायलिसिस आहार के लिए किडनी-अनुकूल है।","12","केक का 1/12 हिस्सा",
["1 पैकेट एंजेल फ़ूड केक मिक्स","8 औंस व्हिप्ड क्रीम चीज़","1/2 कप स्ट्रॉबेरी प्रिज़र्व (जैम)","2 कप वसा-रहित Reddi-Wip® डेयरी व्हिप्ड टॉपिंग"],
["पैकेट पर दिए निर्देशों के अनुसार एंजेल फ़ूड केक बेक करें। कमरे के तापमान तक ठंडा होने दें।","व्हिप्ड क्रीम चीज़ और स्ट्रॉबेरी प्रिज़र्व को चिकना होने तक फेंटें। व्हिप्ड टॉपिंग को धीरे से मिलाएँ।","एंजेल फ़ूड केक को आड़ा काटकर तीन बराबर परतों में बाँटें।","क्रीम चीज़ के मिश्रण का 1/3 हिस्सा परतों के बीच फैलाएँ और परतों को वापस जोड़ दें, बचे हुए 1/3 क्रीम चीज़ मिश्रण को ऊपर फैलाएँ।","परोसने तक फ्रिज में रखें।"],
["बेक करने के बाद एंजेल फ़ूड केक को काँच की बोतल पर उलटा रख दें ताकि केक बैठ न जाए।","क्रीम चीज़ जैसे कम वसा वाले उत्पादों में अक्सर सामान्य वसा वाले उत्पाद की तुलना में सोडियम अधिक होता है। लेबल की तुलना करें और अपने व्यक्तिगत आहार के लिए सबसे अच्छा विकल्प चुनें।","Reddi-Wip® एक दबाव वाला (प्रेशराइज़्ड) डेज़र्ट व्हिप्ड टॉपिंग है जो ज़्यादातर किराने की दुकानों के डेयरी सेक्शन में मिलता है। अगर उपलब्ध न हो, तो फॉस्फेट योजक रहित कोई भी व्हिप्ड टॉपिंग इस्तेमाल करें।"],
["1 स्टार्च","1-1/2 उच्च कैलोरी","2 वसा"]))
r.append(R(3929,"सुपर टेंडर चिकन","बेहद स्वादिष्ट और बेहद मुलायम, DaVita रीनल आहार विशेषज्ञ जेनिस की पड़ोसी वोना की इस किडनी-अनुकूल रेसिपी का वर्णन करने का यही सबसे अच्छा तरीका है। सुपर टेंडर चिकन आसानी से आपके साप्ताहिक पसंदीदा व्यंजनों में से एक बन सकता है।","6","2 औंस चिकन, सॉस का 1/6 हिस्सा",
["1 लहसुन की कली","1 मध्यम प्याज़","2 मध्यम लाल सेब","1 बड़ा चम्मच मैदा (ऑल-पर्पज़ व्हाइट फ़्लोर)","1-1/2 छोटे चम्मच सूखी रगड़ी हुई सेज","1 छोटा चम्मच सूखी थाइम की पत्तियाँ","1/2 छोटा चम्मच पिसा ऑलस्पाइस","1/2 छोटा चम्मच पेपरिका","1/2 छोटा चम्मच नमक","1 पाउंड बिना हड्डी और बिना त्वचा वाले चिकन ब्रेस्ट","2 बड़े चम्मच जैतून का तेल","1/2 कप सेब का जूस","1 बड़ा चम्मच दबाकर भरी हुई ब्राउन शुगर"],
["लहसुन को बारीक काटें और प्याज़ तथा सेब (छिलके के साथ) को पतले स्लाइस में काटें।","एक गैलन आकार के ज़िप-लॉक बैग में मैदा और सारे मसाले मिलाएँ। बंद बैग में सारी सामग्री को हिलाकर चिकन ब्रेस्ट पर मिश्रण की परत चढ़ाएँ।","एक बड़ी कड़ाही में मध्यम आँच पर तेल गरम करें। चिकन डालें और दोनों तरफ़ से भूरा करें।","चिकन को कड़ाही से निकाल लें। प्याज़ और लहसुन डालें। 3 मिनट या नरम होने तक पकाएँ और चलाएँ।","सेब डालें। 2 मिनट पकाएँ और चलाएँ।","सेब का जूस, ब्राउन शुगर और पका हुआ चिकन डालकर चलाएँ और उबाल आने दें। आँच धीमी करें, ढक दें और 10 से 15 मिनट या मनचाही मुलायमियत तक धीमी आँच पर पकाएँ।"],
["जेनिस ने इस रेसिपी के लिए एक और नाम बनाया है: “इस चिकन को खाने के लिए दाँतों की ज़रूरत नहीं।”","चाहें तो चरण #3 में भूरा करने से पहले चिकन ब्रेस्ट को टुकड़ों में काट लें।","अपनी पसंद की किसी भी किस्म का सेब इस्तेमाल करें।","अगर आपके आहार में अधिक प्रोटीन चाहिए, तो प्रोटीन को 27 ग्राम तक बढ़ाने के लिए 4 सर्विंग में बाँटें।"],
["2 मांस","1 फल, कम पोटैशियम"]))
r.append(R(3933,"डिजॉन ड्रेसिंग","चटपटी डिजॉन सरसों, बाल्सेमिक सिरका और एक्स्ट्रा वर्जिन जैतून का तेल मिलकर डिजॉन ड्रेसिंग को बाज़ार में बनी सलाद ड्रेसिंग के लिए लगभग एकदम सही किडनी-अनुकूल, कम सोडियम वाला विकल्प बनाते हैं।","7","2 बड़े चम्मच",
["1 लहसुन की कली","2 बड़े चम्मच डिजॉन सरसों","1/4 कप बाल्सेमिक सिरका","1 छोटा चम्मच चीनी","1/4 छोटा चम्मच काली मिर्च","1/2 कप एक्स्ट्रा वर्जिन जैतून का तेल"],
["लहसुन को कुचलें। पहली 5 सामग्री को फेंटनी से अच्छी तरह मिलाएँ।","जैतून के तेल को धीरे-धीरे फेंटते हुए तब तक मिलाएँ जब तक सामग्री अलग न होने लगे।","बची हुई ड्रेसिंग को कसकर बंद जार में रखें और परोसने तक फ्रिज में रखें। यह 2 सप्ताह तक चलती है।"],
["यह ड्रेसिंग कुरकुरे रोमेन लेट्यूस पर ग्रिल किए हुए स्टेक या चिकन के साथ परोसने पर स्वादिष्ट मुख्य व्यंजन वाला सलाद बनाती है।","अगर उपलब्ध हो, तो अम्ल और मिठास के स्वादों के सही संतुलन के लिए पुराना (एज्ड) बाल्सेमिक सिरका इस्तेमाल करें।"],
["3 वसा"]))
r.append(R(3934,"क्यूकंबर मिंट सलाद","न्यू जर्सी की DaVita आहार विशेषज्ञ क्रिस्टीन का क्यूकंबर मिंट सलाद खीरे और पुदीने से दोहरी ताज़गी देता है। यह किडनी-अनुकूल मुख्य व्यंजन के साथ परोसने के लिए एकदम सही कम सोडियम वाला व्यंजन है।","4","1/2 कप",
["1 अंग्रेज़ी खीरा (इंग्लिश क्यूकंबर)","2 छोटे चम्मच एक्स्ट्रा वर्जिन जैतून का तेल","2 बड़े चम्मच ताज़ा पुदीना या 1 बड़ा चम्मच सूखा पुदीना","1/4 छोटा चम्मच काली मिर्च","1/4 छोटा चम्मच लहसुन पाउडर"],
["खीरे को धोकर छोटे टुकड़ों में काटें; ताज़ा पुदीना काटें। खीरा और पुदीना एक कटोरे में रखें।","जैतून का तेल, काली मिर्च और लहसुन पाउडर डालें। अच्छी तरह मिलाएँ।","ठंडा करने के लिए फ्रिज में रखें। चाहें तो परोसने से पहले थोड़ा सिरका डालें।"],
["अपने स्वाद के अनुसार और मसाले डालें।"],
["1 सब्जी, कम पोटैशियम"]))
r.append(R(3937,"पुल्ड चिकन","DaVita आहार विशेषज्ञ एमे का पुल्ड चिकन ऐसी रेसिपी है जिसे आप एक से ज़्यादा बार बनाएँगे। चिकन और सब्जियों को क्रॉक पॉट में रख दें और कुछ घंटों बाद अब तक का सबसे मुलायम चिकन पाएँ। सैंडविच बनाएँ या पुल्ड चिकन को चावल या अनाज के साथ परोसें।","10","1 कप",
["2-1/2 पाउंड जमे हुए, बिना हड्डी और बिना त्वचा वाले चिकन ब्रेस्ट","1-1/4 कप डिब्बाबंद टमाटर प्यूरी","2 मध्यम मीठे प्याज़","3 मध्यम गाजर","3 शिमला मिर्च","1 तीखी मिर्च","6 लहसुन की कलियाँ","1/2 छोटा चम्मच जीरा"],
["चिकन को पिघलाएँ। एक बड़े Crock-Pot® में टमाटर प्यूरी और चिकन मिलाएँ।","बाकी सारी सामग्री को फ़ूड प्रोसेसर में प्यूरी करें (ज़्यादातर फ़ूड प्रोसेसर में इसे हिस्सों में करना पड़ेगा)।","सब्जियाँ Crock-Pot में डालें और हाई पर 4 घंटे या लो पर 6-8 घंटे पकाएँ।","चिकन को प्लेट में निकालें। 2 काँटों से चिकन को रेशे-रेशे करें, फिर उसे Crock-Pot® में सॉस में वापस डाल दें।"],
["तैयार होने पर चिकन चिमटे या काँटे से आसानी से अलग हो जाना चाहिए।","अपनी पसंद की तीखाहट के अनुसार तीखी मिर्च का प्रकार चुनें।","रेशेदार चिकन को चावल पर या बन में परोसें।","कम प्रोटीन वाले आहार के लिए मात्रा घटाकर 1/2 कप करें और इसे 2 मांस विकल्प गिनें।"],
["4 मांस","1 सब्जी, मध्यम पोटैशियम"]))
r.append(R(3939,"दाल फ्राई","सफ़ेद चावल के साथ परोसी गई दाल फ्राई किडनी-अनुकूल आहार के लिए एक स्वादिष्ट भोजन है।","4","3/4 कप",
["2 छोटे चम्मच वनस्पति तेल","1 छोटा चम्मच काली सरसों के दाने","1 छोटा चम्मच साबुत जीरा","1/2 कप प्याज़","1 हरी मिर्च","1 छोटा चम्मच अदरक","1 कप हरी मसूर, नरम पकी हुई","1-1/2 कप पानी","1/4 छोटा चम्मच नमक","1/2 छोटा चम्मच सरसों पाउडर","1/2 छोटा चम्मच लाल मिर्च पाउडर","2 छोटे चम्मच नींबू का रस","1 बड़ा चम्मच धनिया","4 कप सफ़ेद चावल, पका हुआ"],
["प्याज़ और हरी मिर्च काटें। अदरक कद्दूकस करें।","एक सॉसपैन में वनस्पति तेल गरम करें। सरसों के दाने और जीरा डालें। जब वे चटकने लगें, तो कटा प्याज़, हरी मिर्च और अदरक डालें। प्याज़ के हल्के भूरे होने तक भूनें।","पकी हुई दाल डालें; 3/4 कप पानी, नमक और सरसों पाउडर डालें। 10 मिनट तक पकाएँ, जब तक दाल मनचाही गाढ़ाई तक न पक जाए।","नींबू का रस डालें और बारीक कटा धनिया बुरकें।","रोटी/चावल के साथ गरमागरम परोसें।"],
["रोटी एक भारतीय चपटी ब्रेड है, जिसे चपाती भी कहा जाता है।","वेट ग्राइंडर दक्षिण भारतीय रसोई के बहुत लोकप्रिय उपकरण हैं और इनका उपयोग भिगोए हुए अनाज और दालों से पेस्ट बनाने के लिए किया जाता है।","इडली लगभग आठ सेंटीमीटर व्यास की गोल, फूली हुई ब्रेड है। इडली पिसे हुए चावल या चावल के आटे को पिसी उड़द दाल, नमक, मेथी (मेथी दाना) और पानी के साथ मिलाकर बनाई जाती है। मिश्रण को इडली स्टीमर में भाप में पकाने से पहले खमीर उठने दिया जाता है। ये दक्षिण भारत की पारंपरिक हैं और अक्सर सांभर के साथ खाई जाती हैं।","अक्सर नाश्ते में या हल्के नाश्ते के रूप में खाई जाने वाली इडली आमतौर पर चटनी, सांभर या अन्य संगत व्यंजनों के साथ जोड़े में परोसी जाती हैं।"],
["2-1/2 स्टार्च","1 सब्जी, मध्यम पोटैशियम"]))
r.append(R(3941,"चना सब्जी सलाद","चने, गाजर, प्याज़ और सेलेरी को नींबू, सरसों और काली मिर्च से मसालेदार बनाकर तैयार किया गया यह आसान, उच्च फ़ाइबर वाला चना सब्जी सलाद है।","6","1/2 कप",
["15.5 औंस डिब्बाबंद चने","1/2 बड़ा प्याज़","2 सेलेरी की डंडियाँ","2 मध्यम गाजर","1/2 ताज़ा नींबू","2-1/2 बड़े चम्मच डिजॉन सरसों","1/2 छोटा चम्मच काली मिर्च"],
["चने निथारकर धो लें। प्याज़, सेलेरी और गाजर को छोटे टुकड़ों में काटें। नींबू का रस निकालें।","चने को एक बड़े मिक्सिंग बाउल में रखें। आलू मैशर या काँटे से मिलने तक मसल लें।","बाकी सामग्री को मसले हुए चनों के साथ मिलाएँ।","परोसने तक फ्रिज में रखें।"],
["कम सोडियम वाले चने ढूँढें। अगर उपलब्ध न हों, तो सबसे कम सोडियम वाला ब्रांड चुनें।","इसे ब्रेड पर या रैप में परोसें या सलाद में डालें, या शिमला मिर्च, खीरा, तोरी, गाजर या सेलेरी की डंडियों जैसी कच्ची सब्जियों या कम सोडियम वाले क्रैकर के लिए डिप के रूप में उपयोग करें।","चलते-फिरते भोजन के लिए इसे ताज़े अंगूर या सेब के स्लाइस के साथ “स्नैक बॉक्स” के हिस्से के रूप में शामिल करें।","चना सलाद अंडे के सलाद का बहुत अच्छा विकल्प है।"],
["1/2 स्टार्च","1 सब्जी, मध्यम पोटैशियम"]))
r.append(R(3942,"आलू और अंडा सैंडविच","यहाँ आलू और अंडे वाला नाश्ते का सैंडविच है, जो नाश्ते की दो मुख्य चीज़ें हैं। DaVita आहार विशेषज्ञ एंजेला ने यह रेसिपी अपने उन डायलिसिस मरीज़ों के लिए बनाई जिन्हें पोटैशियम पर ध्यान रखना होता है। आलू और अंडा सैंडविच को किडनी-अनुकूल रखने के लिए उन्होंने आलू में पोटैशियम कम करने के 2 तरीके शामिल किए हैं।","4","1 सैंडविच",
["1 मध्यम बेकिंग आलू","2 बड़े चम्मच कैनोला तेल","6 बड़े अंडे","4 साबुत गेहूँ के Oroweat® सैंडविच थिन्स","4 छोटे चम्मच सालसा"],
["उपयोगी सुझावों में नीचे दिखाए गए तरीकों में से किसी एक से आलू में पोटैशियम कम करें। (अगर आपको कम पोटैशियम वाला आहार नहीं चाहिए, तो यह चरण छोड़ दें।)","कड़ाही में तेल गरम करें और कटे हुए आलू डालें। आलू के भूरे होने तक पकाएँ।","अंडे फेंटें और आलू पर डालें। आँच धीमी करें और अंडे के जमने तक 2-3 मिनट अंडे को आलू के साथ चलाएँ।","अंडे और आलू के मिश्रण को चम्मच से सैंडविच थिन्स पर बराबर रखें। चाहें तो हर सैंडविच पर एक छोटा चम्मच सालसा डालें। सैंडविच बनाने के लिए सैंडविच थिन का ऊपरी हिस्सा रखें और आनंद लें।"],
["सैंडविच थिन्स की जगह साबुत गेहूँ का टोस्ट या नरम गरम आटे की टॉर्टिला (फ़ाजिटा आकार की) इस्तेमाल करें।","एक मध्यम बेकिंग आलू का वज़न लगभग 12 औंस होता है।","आलू में पोटैशियम कम करने की दो बार पकाने की तकनीक: आलू छीलें और पतले स्लाइस में काटें, छोटे टुकड़ों में काटें या हैश ब्राउन के लिए कद्दूकस करें। आलू के टुकड़ों को पानी के बर्तन में रखें और उबाल आने दें। पानी निथारें, फिर ताज़ा पानी डालें। पानी में उबाल आने दें और आलू के नरम होने तक पकाएँ। पानी निथारें और आलू को अपनी इच्छा के अनुसार तैयार करें। दो बार पकाने की विधि 100 ग्राम की मात्रा (2/3 कप) में पोटैशियम को 200 मिग्रा से कम कर देती है।","आलू में पोटैशियम कम करने की एक और प्रसिद्ध तकनीक है आलू के टुकड़े काटकर उन्हें पानी में भिगोना। इस तकनीक के बारे में और जानने के लिए DaVita.com पर लेख “Lowering Potassium in Potatoes” पढ़ें।"],
["1-1/2 मांस","2 स्टार्च","1/2 सब्जी, मध्यम पोटैशियम","1 वसा"]))
r.append(R(3943,"गार्लिक ऑयस्टर क्रैकर्स","गार्लिक ऑयस्टर क्रैकर्स किसी भी किडनी आहार के लिए एक स्वादिष्ट साइड डिश है, चाहे आपको किडनी रोग हो, मधुमेह हो या आप डायलिसिस पर हों।","14","1/2 कप",
["1/2 कप बटर-फ़्लेवर वाला पॉपकॉर्न तेल","1 बड़ा चम्मच लहसुन पाउडर","7 कप ऑयस्टर क्रैकर्स","2 छोटे चम्मच सूखी सोया (डिल वीड)"],
["ओवन को 250° F पर पहले से गरम करें।","एक बड़े कटोरे में तेल और लहसुन पाउडर मिलाएँ। क्रैकर्स डालकर चलाएँ ताकि वे बराबर लिपट जाएँ।","सोया छिड़कें और उछालकर मिलाएँ।","क्रैकर्स को कुकी शीट पर फैलाएँ और 45 मिनट बेक करें। हर 15 मिनट पर धीरे से मिलाएँ।","क्रैकर्स को ठंडा करने के लिए पेपर टॉवल पर फैलाएँ। परोसने तक हवाबंद डिब्बे में रखें।"],
["12 औंस के एक बैग ऑयस्टर क्रैकर्स में 7 कप होते हैं।","नाश्ते की मात्रा में छोटे पेपर कप में परोसें।","और तीखे मिश्रण के लिए अपनी पसंद का कम सोडियम वाला हर्ब सीज़निंग या चिली पाउडर डालें।"],
["1 स्टार्च","1 वसा"]))
